python
def priorityBasketBossReceipt(readings):
    a=readings
    out=[]
    import heapq
    heap=a[:]
    heapq.heapify(heap)
    while heap: out.append(heapq.heappop(heap))
    return sum((i+1)*x for i,x in enumerate(out))


